                "url": "https://www.imdb.com/title/tt35196915/",
                "primaryTitle": "Scham",
                "originalTitle": "Scham",
                "type": "movie",
                "description": "Aaron (Til Schindler) hatte eine traumatische Kindheit. Er wurde von seiner Mutter Susanne (Heike Hanold-Lynch) ständig geschlagen, immer wieder übte sie sowohl körperliche, als auch psychische Gewalt gegen ihn aus. Im Alter von sieben Jahren wurde er dann von einem Unbekannten sexuell missbraucht. Daraufhin begann er, mit anderen gleichaltrigen Kindern Sex zu haben. Heute, als junger Erwachsener, ist er immer noch traumatisiert und schämt sich zutiefst. Als er seine Mutter nach vier Jahren Funkstille wieder besucht, ist er bereit, sein Schweigen zu brechen. Er wirft ihr vor, ihn als Kind nicht nur nicht beschützt, sondern auch selbst gequält zu haben. Zu seiner Überraschung geht sie in die Offensive und hält ihm vor, ihr Leben ruiniert zu haben. Doch trotz der beiden entgegengesetzten Standpunkte und der harten gegenseitigen Anschuldigungen suchen die beiden nach Wegen, wieder zusammenzufinden.",
                "primaryImage": "https://m.media-amazon.com/images/M/MV5BMTBiODI3ZTQtZWIxZC00ZDZjLTlhZjktNGM4NWNmZGY2MjdmXkEyXkFqcGc@.jpg",
